using System.Collections;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "EtherealConvergenceAction", menuName = "Data/Battle/Battle Actions/Orion/EtherealConvergence Action")]
public class EtherealConvergenceAction : BattleAction
{
	[Header("Sunken Curse")]
	[SerializeField]
	private DefaultEffectAction gainTickAction;

	[SerializeField]
	private StarRequirementAction starRequirementAction;

	[Header("VFX")]
	[SerializeField]
	private float vfxDelay;

	public override bool CheckConditionToBeCasted(int actionValue)
	{
		if (GetAstriumToAdd() > 0)
		{
			return starRequirementAction.CheckConditionToBeCasted(actionValue);
		}
		return false;
	}

	public override void CastTarget(GameObject target, GameObject source)
	{
		if (IsVFXEnabled())
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(VFXDelay(target, source));
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		}
		else
		{
			CheckCancelAutoOnDiceCastedOnRuneCasted(source);
			gainTickAction.CastTargetAmount(target, GetAstriumToAdd(), source);
		}
	}

	private IEnumerator VFXDelay(GameObject target, GameObject source)
	{
		PlaySFX();
		SpawnVFXOnPlayerPosition(3f);
		yield return new WaitForSeconds(vfxDelay);
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
		gainTickAction.CastTargetAmount(target, GetAstriumToAdd(), source);
	}

	private int GetAstriumToAdd()
	{
		int num = ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().IsPlayerAstriumGetAmount(activateFeedback: false);
		return 9 - num;
	}
}
